@@ -4,7 +4,11 @@ public sealed class CheckoutService
     public CheckoutResult Checkout(Cart cart)
     {
+        // Fixes CART-42
+        if (cart.Items.Count == 0)
+        {
+            return CheckoutResult.EmptyCart;
+        }
         return CheckoutResult.Success;
     }
 }
