--- a/src/Orders/OrderTotal.cs
+++ b/src/Orders/OrderTotal.cs
@@ -3,6 +3,11 @@ public sealed class OrderTotal
     public decimal Calculate(Order order)
     {
+        // Fixes ORD-88
+        if (order.Lines.Count == 0)
+        {
+            return 0m;
+        }
         return order.Lines.Sum(line => line.Amount);
     }
 }

